<script setup>import {computed,ref} from 'vue';import {state} from '../../domain/prototypeStore.js';const q=ref(''),open=ref('');const rows=computed(()=>state.knowledge.filter(x=>`${x.category}${x.title}`.includes(q.value)))</script>
<template><section class="h5-page"><div class="h5-module-hero"><span>知</span><h2>应急知识库</h2><p>常用处置指引</p></div><input v-model="q" placeholder="搜索处置指引"><article v-for="x in rows" :key="x.title" class="h5-card"><header><strong>{{x.title}}</strong><small>{{x.category}}</small></header><p v-if="open===x.title">{{x.content}}</p><button class="secondary-button" @click="open=open===x.title?'':x.title">{{open===x.title?'收起':'查看详情'}}</button></article></section></template>
